use kimo_core::{commands::{Session,dispatch},effects::{Frame,Params},keyframe::Prop,color::node_graph::{Graph,Node}};use serde_json::json;use std::collections::BTreeMap;
fn graph(kind:&str,params:Params,strings:BTreeMap<String,String>)->Graph{let mut g=Graph::default();g.nodes.insert("a".into(),Node{id:"a".into(),kind:"grade".into(),inputs:vec!["input".into()],weights:vec![Prop::new(1.)],effect:Some(kimo_core::model::Effect{id:"a".into(),kind:kind.into(),params,strings}),mask:None,bypass:false});g.output="a".into();g}
fn frame()->Frame{Frame{w:65,h:33,d:(0..65*33).flat_map(|i|[i as f32/2145.,((i*37)%2145) as f32/2145.,0.4,1.]).collect()}}
#[test]fn spatial_full_canvas_exact_and_diamond(){for kind in ["blur","sharpen"]{let mut p=Params::new();p.insert("radius".into(),Prop::new(4.));let g=graph(kind,p.clone(),Default::default());let mut a=frame();let mut b=frame();kimo_core::effects::apply(kind,&p,&Default::default(),&mut a,0.,0).unwrap();g.apply(&mut b,0.,0,25.).unwrap();assert_eq!(a.d,b.d);let original=b.d.clone();let mut repeat=frame();g.apply(&mut repeat,0.,0,25.).unwrap();assert_eq!(original,repeat.d);}let mut g=graph("blur",Default::default(),Default::default());g.nodes.get_mut("a").unwrap().effect.as_mut().unwrap().params.insert("radius".into(),Prop::new(513.));assert!(g.apply(&mut frame(),0.,0,25.).is_err());}
#[test]fn staple_curves_log_wheels_exact(){for(kind,k,v)in[("hue_curves","hvh0",15.),("hue_curves","hvs3",1.4),("hue_curves","hvl6",0.1),("log_wheels","shadow_r",0.1),("rgb_curves","r2",0.4)]{let p=BTreeMap::from([(k.into(),Prop::new(v))]);let g=graph(kind,p.clone(),Default::default());let mut a=frame();let mut b=frame();kimo_core::effects::apply(kind,&p,&Default::default(),&mut a,0.,0).unwrap();g.apply(&mut b,0.,0,25.).unwrap();assert_eq!(a.d,b.d);}}
fn session()->(Session,serde_json::Value){let mut s=Session::new();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].clone();(s,c)}
#[test]fn generated_file_lut_parity_persistence_and_error(){let(mut s,c)=session();let r=dispatch(&mut s,"generate_lut_node",&json!({"clip_id":c,"node_id":"generated","size":17,"steps":[{"type":"effect","kind":"exposure","params":{"stops":{"base":-1}}}]})).unwrap();assert!(r["approximation"]["max_abs"].as_f64().unwrap()<1e-6);dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"generated"})).unwrap();let n=dispatch(&mut s,"inspect_grade_graph",&json!({"clip_id":c})).unwrap()["graph"]["nodes"]["generated"].clone();let text=n["effect"]["strings"]["cube_text"].as_str().unwrap();let path=format!("/tmp/node-lut-{}.cube",std::process::id());std::fs::write(&path,text).unwrap();let file=graph("lut",Default::default(),BTreeMap::from([("path".into(),path.clone())]));let g= s.project.find_clip_mut(c.as_str().unwrap()).unwrap().grade_graph.clone().unwrap();let mut a=frame();let mut b=frame();g.apply(&mut a,0.,0,25.).unwrap();file.apply(&mut b,0.,0,25.).unwrap();assert_eq!(a.d,b.d);let serialized=serde_json::to_vec(&s.project).unwrap();let p:kimo_core::model::Project=serde_json::from_slice(&serialized).unwrap();assert!(serde_json::to_value(p).unwrap().to_string().contains("cube_text"));std::fs::remove_file(path).unwrap();let before=serde_json::to_value(&s.project).unwrap();assert!(dispatch(&mut s,"generate_lut_node",&json!({"clip_id":c,"node_id":"bad","size":17,"steps":[{"type":"effect","kind":"blur"}]})).is_err());assert_eq!(before,serde_json::to_value(&s.project).unwrap());}
#[cfg(feature="native-ocio")]
#[test]fn shared_native_generated_lut(){let(mut s,_)=session();dispatch(&mut s,"create_shared_grade_graph",&json!({"id":"native"})).unwrap();let path=concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio");let v=dispatch(&mut s,"generate_lut_node",&json!({"shared_graph_id":"native","node_id":"gamma","size":17,"steps":[{"type":"ocio","config_path":path,"source":"ACEScg","destination":"DisplayGamma2"}]})).unwrap();assert!(v["approximation"]["max_abs"].as_f64().unwrap()>0.01);assert!(v["approximation"]["max_abs"].as_f64().unwrap()<0.07);dispatch(&mut s,"set_grade_output",&json!({"shared_graph_id":"native","node_id":"gamma"})).unwrap();let a=dispatch(&mut s,"evaluate_grade_graph_samples",&json!({"shared_graph_id":"native","rgba":[0.25,0.25,0.25,1.]})).unwrap();assert!((a["rgba"][0].as_f64().unwrap()-0.5).abs()<1e-5);let b=dispatch(&mut s,"evaluate_grade_graph_samples",&json!({"shared_graph_id":"native","rgba":[0.25,0.25,0.25,1.]})).unwrap();assert_eq!(a,b);println!("native generated17 approximation {}",v["approximation"]);}
#[test]fn spatial_mask_alpha_and_noncommuting_order(){let mut g=graph("sharpen",Default::default(),Default::default());let mut m=kimo_core::masks::new_layer("m".into(),"ellipse");m.props.insert("w".into(),Prop::new(0.5));g.nodes.get_mut("a").unwrap().mask=Some(m);let mut f=frame();for(i,c)in f.d.chunks_exact_mut(4).enumerate(){c[3]=i as f32/2145.;}let oldalpha:f64=f.d.chunks_exact(4).map(|c|c[3] as f64).sum();g.apply(&mut f,0.,0,25.).unwrap();assert_eq!(oldalpha,f.d.chunks_exact(4).map(|c|c[3] as f64).sum::<f64>());
let p=BTreeMap::from([("radius".into(),Prop::new(3.))]);let mut a=frame();let mut b=frame();kimo_core::effects::apply("blur",&p,&Default::default(),&mut a,0.,0).unwrap();kimo_core::effects::apply("hue_curves",&BTreeMap::from([("hvs2".into(),Prop::new(0.))]),&Default::default(),&mut a,0.,0).unwrap();kimo_core::effects::apply("hue_curves",&BTreeMap::from([("hvs2".into(),Prop::new(0.))]),&Default::default(),&mut b,0.,0).unwrap();kimo_core::effects::apply("blur",&p,&Default::default(),&mut b,0.,0).unwrap();assert_ne!(a.d,b.d);}
#[test]fn real_file_generated_spatial_parity(){let input="/tmp/node-real-before.f32";if !std::path::Path::new(input).exists(){return}let bytes=std::fs::read(input).unwrap();let raw=Frame{w:640,h:360,d:bytes.chunks_exact(4).map(|v|f32::from_le_bytes(v.try_into().unwrap())).collect()};let(mut s,c)=session();dispatch(&mut s,"generate_lut_node",&json!({"clip_id":c,"node_id":"lut","size":17,"steps":[{"type":"effect","kind":"exposure","params":{"stops":{"base":-0.125}}}]})).unwrap();dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":"sharp","parent":"lut","kind":"grade","effect_kind":"sharpen","params":{"radius":2,"amount":0.3}})).unwrap();dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"sharp"})).unwrap();let g=s.project.find_clip_mut(c.as_str().unwrap()).unwrap().grade_graph.clone().unwrap();let e=g.nodes["lut"].effect.as_ref().unwrap();let mut reference=Frame{w:raw.w,h:raw.h,d:raw.d.clone()};kimo_core::effects::apply("lut",&e.params,&e.strings,&mut reference,0.,0).unwrap();let e=g.nodes["sharp"].effect.as_ref().unwrap();kimo_core::effects::apply("sharpen",&e.params,&e.strings,&mut reference,0.,0).unwrap();let mut after=Frame{w:raw.w,h:raw.h,d:raw.d.clone()};g.apply(&mut after,0.,0,25.).unwrap();assert_eq!(reference.d,after.d);let mut repeat=Frame{w:raw.w,h:raw.h,d:raw.d.clone()};g.apply(&mut repeat,0.,0,25.).unwrap();assert_eq!(repeat.d,after.d);for(p,f)in[("/tmp/expand-real-before.f32",raw),("/tmp/expand-real-after.f32",after)]{std::fs::write(p,f.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();}}
